// ================================================================
// 30-Day Robotics Lab - Module 1: Sense -> Process -> Decide -> Act
// Project: Autonomous 2WD Obstacle Avoidance Rover (Arduino Uno)
// ================================================================

const int TRIG_PIN = 9;       // Ultrasonic Trigger Pin
const int ECHO_PIN = 10;      // Ultrasonic Echo Pin
const int ENA = 5;            // Motor Left Speed (PWM)
const int IN1 = 6;            // Motor Left Direction 1
const int IN2 = 7;            // Motor Left Direction 2
const int IN3 = 8;            // Motor Right Direction 1
const int IN4 = 11;           // Motor Right Direction 2
const int ENB = 3;            // Motor Right Speed (PWM)

const int DISTANCE_THRESHOLD = 20; // Collision threshold in cm

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
  pinMode(ENB, OUTPUT);

  Serial.println("[ROBO-LAB] Module 1: Obstacle Avoidance Rover Initialized.");
  delay(1000);
}

// SENSE: Calculate distance in centimeters
int measureDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000); // 30ms timeout
  if (duration == 0) return 100; // Path clear if timeout
  return duration * 0.034 / 2;
}

void moveForward() {
  analogWrite(ENA, 180);
  analogWrite(ENB, 180);
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);
}

void stopMotors() {
  analogWrite(ENA, 0);
  analogWrite(ENB, 0);
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, LOW);
}

void turnLeft() {
  analogWrite(ENA, 160);
  analogWrite(ENB, 160);
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH); // Reverse left
  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);  // Forward right
}

void loop() {
  // 1. SENSE
  int distance = measureDistance();
  Serial.print("Sensor Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  // 2. PROCESS & 3. DECIDE
  if (distance < DISTANCE_THRESHOLD) {
    // 4. ACT: Obstacle detected within 20cm!
    Serial.println("-> DECISION: Obstacle detected! Halting and Turning Left.");
    stopMotors();
    delay(200);
    turnLeft();
    delay(400); // Rotate ~45-90 degrees
  } else {
    // 4. ACT: Path is clear
    Serial.println("-> DECISION: Path is clear. Cruising Forward.");
    moveForward();
  }
  delay(100); // 5. SENSE AGAIN in next loop cycle
}
